1013→// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
1014→func (s *GitStore) ensureSessionsBranch() error {
1015→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1016→	_, err := s.repo.Reference(refName, true)
1017→	if err == nil {
1018→		return nil // Branch exists
1019→	}
1020→
1021→	// Create orphan branch with empty tree
1022→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
1023→	if err != nil {
1024→		return err
1025→	}
1026→
1027→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
1028→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
1029→	if err != nil {
1030→		return err
1031→	}
1032→
1033→	newRef := plumbing.NewHashReference(refName, commitHash)
1034→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1035→		return fmt.Errorf("failed to set branch reference: %w", err)
1036→	}
1037→	return nil
1038→}
