1040→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
1041→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
1042→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
1043→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1044→	ref, err := s.repo.Reference(refName, true)
1045→	if err != nil {
1046→		// Local branch doesn't exist, try remote-tracking branch
1047→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
1048→		ref, err = s.repo.Reference(remoteRefName, true)
1049→		if err != nil {
1050→			return nil, fmt.Errorf("sessions branch not found: %w", err)
1051→		}
1052→	}
1053→
1054→	commit, err := s.repo.CommitObject(ref.Hash())
1055→	if err != nil {
1056→		return nil, fmt.Errorf("failed to get commit object: %w", err)
1057→	}
1058→
1059→	tree, err := commit.Tree()
1060→	if err != nil {
1061→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
1062→	}
1063→
1064→	return tree, nil
1065→}
