1191→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
1192→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1193→	// Get repository config (includes local settings)
1194→	cfg, err := repo.Config()
1195→	if err == nil {
1196→		name = cfg.User.Name
1197→		email = cfg.User.Email
1198→	}
1199→
1200→	// Provide sensible defaults if git user is not configured
1201→	if name == "" {
1202→		name = "Unknown"
1203→	}
1204→	if email == "" {
1205→		email = "unknown@local"
