		expected bool
	}{
		{"Regular file", "src/main.go", true},
		{"Gitignore", ".gitignore", true},
		{"Gitattributes", ".gitattributes", true},
		{"Hidden file", ".hidden", false},
		{"Hidden directory file", ".config/file.txt", false},
		{"Python cache", "file.pyc", false},
